## 统一注册本工程用到的输入动作。
## project.godot 里已经声明了同样的动作，这里只是兜底：
## 即使脚本被单独加载 / 场景被单独运行，InputMap 也是完整的。

const KEY_ACTIONS := {
	&"move_forward": [KEY_W, KEY_UP],
	&"move_back": [KEY_S, KEY_DOWN],
	&"move_left": [KEY_A, KEY_LEFT],
	&"move_right": [KEY_D, KEY_RIGHT],
	&"jump": [KEY_SPACE],
	&"weapon_toggle": [KEY_Q],
	&"weapon_pistol": [KEY_1],
	&"weapon_sword": [KEY_2],
	&"release_mouse": [KEY_ESCAPE],
}

const MOUSE_ACTIONS := {
	&"fire": [MOUSE_BUTTON_LEFT],
}


static func ensure_actions() -> void:
	for action in KEY_ACTIONS.keys():
		_ensure_action(action, KEY_ACTIONS[action], true)
	for action in MOUSE_ACTIONS.keys():
		_ensure_action(action, MOUSE_ACTIONS[action], false)


static func _ensure_action(action: StringName, codes: Array, is_keyboard: bool) -> void:
	if InputMap.has_action(action):
		return
	InputMap.add_action(action, 0.2)
	for code in codes:
		if is_keyboard:
			var key_event := InputEventKey.new()
			key_event.device = -1
			key_event.physical_keycode = code
			InputMap.action_add_event(action, key_event)
		else:
			var mouse_event := InputEventMouseButton.new()
			mouse_event.device = -1
			mouse_event.button_index = code
			InputMap.action_add_event(action, mouse_event)
